solution.solution.js:
function validateSignup(values) {
  const errors = {};
  const name = (values.name ?? "").trim();
  const email = (values.email ?? "").trim().toLowerCase();
  const ageText = (values.age ?? "").trim();
  const password = values.password ?? "";

  if (name.length < 2) errors.name = "Enter at least 2 characters.";

  const at = email.indexOf("@");
  const validEmail = at > 0 && email.indexOf("@", at + 1) === -1 && email.slice(at + 1).includes(".");
  if (!validEmail) errors.email = "Enter a valid email.";

  let age = null;
  if (ageText !== "") {
    age = Number(ageText);
    if (!Number.isInteger(age) || age < 13 || age > 120) errors.age = "Enter an age from 13 to 120.";
  }

  const chars = [...password];
  const hasLetter = chars.some(c => c.toLowerCase() >= "a" && c.toLowerCase() <= "z");
  const hasDigit = chars.some(c => c >= "0" && c <= "9");
  if (password.length < 8 || !hasLetter || !hasDigit) {
    errors.password = "Use 8 or more characters with a letter and a digit.";
  } else if (values.confirm !== password) {
    errors.confirm = "The passwords do not match.";
  }

  const ok = Object.keys(errors).length === 0;
  return { ok, data: ok ? { name, email, age } : null, errors };
}

function keyCommand(event) {
  const mod = event.ctrlKey || event.metaKey;
  const key = event.key.length === 1 ? event.key.toLowerCase() : event.key;
  if (mod) {
    if (key === "s" && !event.shiftKey) return "save";
    if (key === "z") return event.shiftKey ? "redo" : "undo";
    if (key === "y" && !event.shiftKey) return "redo";
    return null;
  }
  if (event.shiftKey) return null;
  if (key === "Escape") return "close";
  if (key === "/") return "search";
  return null;
}

unitTests:
const good = { name: " Ada ", email: " Ada@Example.org ", age: "36", password: "secret12", confirm: "secret12" };

test("a valid form", () => {
  checkEq(validateSignup(good), { ok: true, data: { name: "Ada", email: "ada@example.org", age: 36 }, errors: {} });
  checkEq(validateSignup({ ...good, age: "" }).data.age, null);
});

test("each field's error", () => {
  const r = validateSignup({ name: "A", email: "a@b", age: "12.5", password: "short1", confirm: "x" });
  checkEq(r.ok, false);
  checkEq(r.data, null);
  checkEq(r.errors, {
    name: "Enter at least 2 characters.",
    email: "Enter a valid email.",
    age: "Enter an age from 13 to 120.",
    password: "Use 8 or more characters with a letter and a digit.",
  });
});

test("email and password details", () => {
  const e = email => validateSignup({ ...good, email }).errors.email;
  checkEq([e("@x.org"), e("a@b@c.org"), e("ab.org"), e("a@x.org")], ["Enter a valid email.", "Enter a valid email.", "Enter a valid email.", undefined]);
  checkEq(validateSignup({ ...good, password: "abcdefgh", confirm: "abcdefgh" }).errors.password !== undefined, true);
  checkEq(validateSignup({ ...good, password: "12345678", confirm: "12345678" }).errors.password !== undefined, true);
  checkEq(validateSignup({ ...good, confirm: "secret13" }).errors, { confirm: "The passwords do not match." });
  checkEq(validateSignup({ ...good, age: "121" }).errors, { age: "Enter an age from 13 to 120." });
  checkEq(validateSignup({}).ok, false);
});

test("keyboard shortcuts", () => {
  const k = (key, mods = {}) => keyCommand({ key, ctrlKey: false, metaKey: false, shiftKey: false, ...mods });
  checkEq(k("s", { ctrlKey: true }), "save");
  checkEq(k("s", { metaKey: true }), "save");
  checkEq(k("z", { ctrlKey: true }), "undo");
  checkEq(k("Z", { ctrlKey: true, shiftKey: true }), "redo");
  checkEq(k("y", { metaKey: true }), "redo");
  checkEq(k("Escape"), "close");
  checkEq(k("/"), "search");
  checkEq(k("s"), null);
  checkEq(k("x", { ctrlKey: true }), null);
  checkEq(k("Escape", { shiftKey: true }), null);
});

